/* ============================================================
   像素风 · 少女心粉色 Pink Pixel Chat · v4
   ============================================================ */

#message-area {
  /* ---------- 调色板 ---------- */
  --px-ink:      #a3436e;   /* 玫瑰粉紫：描边 / 硬阴影 */
  --px-ink-soft: #c96a92;   /* 柔和装饰色 */
  --px-bg:       #fff0f7;   /* 草莓牛奶底 */
  --px-b-1:      #fffdfe;   /* 对方气泡 上 */
  --px-b-2:      #fff2f9;   /* 对方气泡 下 */
  --px-me-1:     #ffc3de;   /* 我的气泡 上 */
  --px-me-2:     #ff9ecb;   /* 我的气泡 下 */
  --px-panel:    #ffe0ef;   /* 思考面板底 */
  --px-lilac:    #eadcff;   /* 心声淡薰衣草 */
  --px-accent:   #ff6b9d;   /* 红包 */
  --px-text:     #5a2a3e;
  --px-text-deep:#3d1024;   /* 思考过程深色字 */

  --chat-bg: var(--px-bg);
  --chat-bubble-bg: var(--px-b-1);
  --chat-text: var(--px-text);

  position: relative;
  padding: 14px 12px;

  /* 粉紫光晕 + 粉色波点 + 极淡扫描线 */
  background-color: var(--px-bg);
  background-image:
    radial-gradient(circle at 18% 10%, rgba(255, 190, 225, .45), transparent 42%),
    radial-gradient(circle at 84% 90%, rgba(215, 185, 255, .35), transparent 42%),
    radial-gradient(circle, rgba(255, 150, 200, .18) 2px, transparent 2.5px),
    repeating-linear-gradient(0deg,
      rgba(255, 140, 190, .04) 0 1px, transparent 1px 12px);
  background-size: auto, auto, 16px 16px, auto;

  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas,
               "Courier New", monospace;
  font-size: 13px;
  line-height: 1.55;
  letter-spacing: .3px;
  color: var(--px-text);
  image-rendering: pixelated;
}

/* ---------- 消息行 ---------- */
#message-area .msg-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 2px 0;
}

/* ---------- 气泡通用：糖霜渐变 ---------- */
#message-area .msg-bubble {
  position: relative;
  padding: 9px 12px;
  border: 2px solid var(--px-ink);
  border-radius: 0;
  background-color: var(--px-b-1);
  background-image: linear-gradient(180deg, var(--px-b-1), var(--px-b-2));
  color: var(--px-text);
  box-shadow:
    inset -2px -2px 0 0 rgba(163, 67, 110, .12),
    inset  2px  2px 0 0 rgba(255, 255, 255, .9),
    3px 3px 0 0 var(--px-ink);
  word-break: break-word;
  transition:
    transform .09s steps(2, end),
    box-shadow .09s steps(2, end);
}
#message-area .msg-bubble:hover {
  transform: translate(-1px, -1px);
  box-shadow:
    inset -2px -2px 0 0 rgba(163, 67, 110, .12),
    inset  2px  2px 0 0 rgba(255, 255, 255, .9),
    4px 4px 0 0 var(--px-ink);
}

#message-area .msg-row.left .msg-bubble {
  background-image: linear-gradient(180deg, var(--px-b-1), var(--px-b-2));
}

/* 我的气泡：糖果粉渐变 */
#message-area .msg-row.right .msg-bubble {
  background-image: linear-gradient(180deg, var(--px-me-1), var(--px-me-2));
  color: #6e2547;
  box-shadow:
    inset -2px -2px 0 0 rgba(163, 67, 110, .18),
    inset  2px  2px 0 0 rgba(255, 255, 255, .6),
    -3px 3px 0 0 var(--px-ink);
}
#message-area .msg-row.right .msg-bubble:hover {
  box-shadow:
    inset -2px -2px 0 0 rgba(163, 67, 110, .18),
    inset  2px  2px 0 0 rgba(255, 255, 255, .6),
    -4px 4px 0 0 var(--px-ink);
}

/* ============================================================
   时间分隔条 · 波点刻度线 + 柔光文字
   ============================================================ */
#message-area .msg-time-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 16px 0 12px;
  padding: 0 6px;

  color: #962a58;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  white-space: nowrap;
  user-select: none;

  /* 白色像素描边 + 一圈粉色柔光 */
  text-shadow:
     1px  0   0 #fff, -1px  0   0 #fff,
     0    1px 0 #fff,  0   -1px 0 #fff,
     1px  1px 0 #fff, -1px -1px 0 #fff,
     1px -1px 0 #fff, -1px  1px 0 #fff,
     0 0 7px rgba(255, 140, 190, .55);
}

/* 两侧：粉色波点线 */
#message-area .msg-time-divider::before,
#message-area .msg-time-divider::after {
  content: "";
  flex: 1 1 auto;
  height: 8px;
  background-image: radial-gradient(circle, var(--px-ink-soft) 1.6px, transparent 1.7px);
  background-size: 7px 7px;
  background-repeat: repeat-x;
  background-position: center;
  opacity: .55;
}

/* ---------- 引用块 ---------- */
#message-area .quote-block {
  margin: 4px 0 8px;
  padding: 6px 8px;
  border: 2px solid var(--px-ink);
  border-left-width: 6px;
  border-radius: 0;
  background-color: #fffdfe;
  background-image: repeating-linear-gradient(
    45deg, rgba(255, 140, 190, .13) 0 4px, transparent 4px 8px);
  box-shadow: 2px 2px 0 0 rgba(163, 67, 110, .3);
  font-size: 12px;
  line-height: 1.5;
  opacity: .97;
}

/* ---------- 语音 ---------- */
#message-area .msg-bubble.voice-bubble {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding-right: 14px;
}
#message-area .msg-voice .wave {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 18px;
}
#message-area .msg-voice .wave span {
  display: block;
  width: 3px;
  min-height: 3px;
  border-radius: 0;
  background: currentColor;
  transform-origin: bottom center;
  animation: px-wave 1.1s steps(4, end) infinite;
}
#message-area .msg-voice .wave span:nth-child(3n)   { animation-delay: .12s; }
#message-area .msg-voice .wave span:nth-child(3n+1) { animation-delay: .24s; }
@keyframes px-wave {
  0%, 100% { transform: scaleY(.35); }
  50%      { transform: scaleY(1); }
}
#message-area .voice-text-inner {
  margin-top: 6px;
  padding: 6px 8px;
  border: 2px dashed rgba(163, 67, 110, .4);
  border-radius: 0;
  background: rgba(255, 255, 255, .65);
  font-size: 12px;
  line-height: 1.6;
}

/* ============================================================
   思考过程 · 深色字（保持）
   ============================================================ */
#message-area .msg-content .msg-think {
  margin: 6px 0;
  padding: 6px 10px;
  border: 2px solid var(--px-ink);
  border-radius: 0;
  background: var(--px-panel);
  box-shadow: 2px 2px 0 0 var(--px-ink);
  font-size: 12px;
  line-height: 1.6;
  color: var(--px-text-deep);
  font-weight: 500;
}
#message-area .msg-content .msg-think::before {
  content: "";
  display: inline-block;
  width: 6px; height: 6px;
  margin-right: 6px;
  background: var(--px-text-deep);
  box-shadow: 0 6px 0 0 var(--px-text-deep);
  vertical-align: 2px;
}

/* ---------- 心声 · 薰衣草 ---------- */
#message-area .msg-content .msg-os {
  margin: 6px 0;
  padding: 6px 10px;
  border: 2px solid var(--px-ink);
  border-radius: 0;
  background-color: var(--px-lilac);
  background-image: repeating-linear-gradient(
    -45deg, rgba(163, 67, 110, .07) 0 4px, transparent 4px 8px);
  box-shadow: 2px 2px 0 0 var(--px-ink);
  font-size: 12px;
  line-height: 1.6;
  color: #5a3d6e;
}

/* ============================================================
   转账卡片 · 奶油蜜桃（更奶）
   ============================================================ */
#message-area .msg-card-transfer {
  position: relative;
  border: 2px solid var(--px-ink);
  border-radius: 0;
  background-color: #fff1d9;
  background-image:
    repeating-linear-gradient(45deg,
      rgba(255, 160, 190, .12) 0 4px, transparent 4px 8px),
    linear-gradient(180deg, #fff8e8, #ffe9c9);
  box-shadow:
    inset -2px -2px 0 0 rgba(163, 67, 110, .14),
    inset  2px  2px 0 0 rgba(255, 255, 255, .85),
    3px 3px 0 0 var(--px-ink);
  color: var(--px-text-deep);
  transition:
    transform .09s steps(2, end),
    box-shadow .09s steps(2, end);
}
#message-area .msg-card-transfer:hover {
  transform: translate(-1px, -1px);
  box-shadow:
    inset -2px -2px 0 0 rgba(163, 67, 110, .14),
    inset  2px  2px 0 0 rgba(255, 255, 255, .85),
    4px 4px 0 0 var(--px-ink);
}
/* 左上小角标：双色像素点 */
#message-area .msg-card-transfer::before {
  content: "";
  position: absolute;
  top: 4px; left: 4px;
  width: 5px; height: 5px;
  background: var(--px-accent);
  box-shadow:
     6px 0 0 0 #ffc3de,
     0 6px 0 0 #ffc3de;
}

/* ============================================================
   红包卡片 · 草莓粉（更甜）
   ============================================================ */
#message-area .msg-card-redpacket {
  position: relative;
  border: 2px solid var(--px-ink);
  border-radius: 0;
  background-color: var(--px-accent);
  background-image:
    repeating-linear-gradient(0deg,
      rgba(255, 255, 255, .12) 0 2px, transparent 2px 6px),
    linear-gradient(180deg, #ff85b0, #ff5c93);
  box-shadow:
    inset -2px -2px 0 0 rgba(163, 67, 110, .25),
    inset  2px  2px 0 0 rgba(255, 255, 255, .45),
    3px 3px 0 0 var(--px-ink);
  color: #fff;
  transition:
    transform .09s steps(2, end),
    box-shadow .09s steps(2, end);
}
#message-area .msg-card-redpacket:hover {
  transform: translate(-1px, -1px);
  box-shadow:
    inset -2px -2px 0 0 rgba(163, 67, 110, .25),
    inset  2px  2px 0 0 rgba(255, 255, 255, .45),
    4px 4px 0 0 var(--px-ink);
}
/* 顶部封口条 */
#message-area .msg-card-redpacket::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 6px;
  background-color: var(--px-ink);
  background-image: repeating-linear-gradient(
    90deg,
    rgba(255, 255, 255, .6) 0 2px, transparent 2px 6px);
}

/* ---------- 图片 ---------- */
#message-area .msg-image {
  display: block;
  max-width: 100%;
  border: 2px solid var(--px-ink);
  border-radius: 0;
  image-rendering: pixelated;
  filter: saturate(1.12) contrast(1.04);
  box-shadow: 3px 3px 0 0 rgba(163, 67, 110, .35);
}
#message-area .msg-image-card {
  position: relative;
  display: inline-block;
  padding: 4px;
  border: 2px solid var(--px-ink);
  border-radius: 0;
  background: #fffdfe;
  box-shadow: 3px 3px 0 0 var(--px-ink);
}
#message-area .msg-image-card .msg-image {
  box-shadow: none;
  border-width: 1px;
}
#message-area .msg-image-desc {
  margin-top: 4px;
  padding-top: 4px;
  border-top: 2px dotted rgba(163, 67, 110, .32);
  font-size: 11px;
  letter-spacing: .5px;
  color: #8a5a72;
}

/* ---------- 头像 ---------- */
#message-area .msg-avatar {
  flex: 0 0 auto;
  width: 36px;
  height: 36px;
  overflow: hidden;
  border: 2px solid var(--px-ink);
  border-radius: 0;
  background: #ffd9ea;
  box-shadow: 2px 2px 0 0 var(--px-ink);
}
#message-area .msg-avatar .avatar-img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 0;
  image-rendering: pixelated;
  filter: contrast(1.05) saturate(1.15);
}

/* ---------- 无障碍 ---------- */
@media (prefers-reduced-motion: reduce) {
  #message-area .msg-bubble,
  #message-area .msg-card-transfer,
  #message-area .msg-card-redpacket { transition: none; }
  #message-area .msg-voice .wave span { animation: none; }
}
